def evaluate_expression(expression):
    """
    Evaluates a given arithmetic expression that contains non-negative integers, addition,
    subtraction, multiplication, and division (integer division).
    """
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left // right)

    def precedence(op):
        if op == '+' or op == '-':
            return 1
        if op == '*' or op == '/':
            return 2
        return 0

    operators = []
    values = []
    i = 0
    while i < len(expression):
        if expression[i] == ' ':
            i += 1
            continue
        if expression[i] == '(':
            operators.append(expression[i])
        elif expression[i] == ')':
            while len(operators) != 0 and operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()
        elif expression[i].isdigit():
            val = 0
            while (i < len(expression) and expression[i].isdigit()):
                val = (val * 10) + int(expression[i])
                i += 1
            values.append(val)
            i -= 1
        else:
            while (len(operators) != 0 and precedence(operators[-1]) >= precedence(expression[i])):
                apply_operator(operators, values)
            operators.append(expression[i])
        i += 1

    while len(operators) != 0:
        apply_operator(operators, values)

    return values[-1]

