def unique_paths_with_obstacles(grid):
    """
    Returns the number of unique paths from the top-left to the bottom-right corner
    in a grid with obstacles.

    :param grid: 2D integer array where 1 represents a blocked cell and 0 an open cell
    :return: number of unique paths
    """
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    n, m = len(grid), len(grid[0])
    dp = [[0] * m for _ in range(n)]

    # Initialization
    dp[0][0] = 1 - grid[0][0]

    # Fill first row
    for j in range(1, m):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j-1]

    # Fill first column
    for i in range(1, n):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]

    # Fill the rest of dp array
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[-1][-1]

def min_operations_to_palindrome(s):
    """
    Returns the minimum number of specified operations required to make the string `s` a palindrome.
    If it is not possible, return -1.
    """
    if s == s[::-1]:
        return 0

    original = s
    operations = 0

    while len(s) > 1:
        if s[0] == s[-1]:
            s = s[1:-1]
        else:
            s = original
            break
        if s == s[::-1]:
            return operations + 1
        operations += 1

    return -1

def longest_digit_substring(s):
    """
    Returns the longest contiguous substring of s that contains only digits.
    If there are multiple substrings of the same length, the first one is returned.
    """
    longest = ""
    current = ""

    for char in s:
        if char.isdigit():
            current += char
            if len(current) > len(longest):
                longest = current
        else:
            current = ""

    return longest

