def solve(board):
    """
    Captures all regions surrounded by 'X' in-place.
    """
    if not board or not board[0]:
        return

    rows, cols = len(board), len(board[0])

    def dfs(x, y):
        if x < 0 or x >= rows or y < 0 or y >= cols or board[x][y] != 'O':
            return
        board[x][y] = 'B'
        dfs(x - 1, y)
        dfs(x + 1, y)
        dfs(x, y - 1)
        dfs(x, y + 1)

    for i in range(rows):
        dfs(i, 0)
        dfs(i, cols - 1)
    for j in range(cols):
        dfs(0, j)
        dfs(rows - 1, j)

    for i in range(rows):
        for j in range(cols):
            if board[i][j] == 'O':
                board[i][j] = 'X'
            elif board[i][j] == 'B':
                board[i][j] = 'O'

def numIslands(grid):
    """
    Returns the number of islands in the given 2D binary grid.
    """
    if not grid:
        return 0

    def dfs(x, y):
        if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or grid[x][y] != '1':
            return
        grid[x][y] = '0'  # mark as visited
        # recursively visit all neighboring cells
        dfs(x + 1, y)
        dfs(x - 1, y)
        dfs(x, y + 1)
        dfs(x, y - 1)

    num_islands = 0

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '1':
                dfs(i, j)
                num_islands += 1

    return num_islands

