from typing import List

def removeDuplicates(nums: List[int]) -> int:
    """
    Removes duplicates in-place such that each unique element appears at most twice.
    Modifies the input array and returns the new length.
    """
    if len(nums) <= 2:
        return len(nums)

    write_index = 2

    for read_index in range(2, len(nums)):
        if nums[read_index] != nums[write_index - 2]:
            nums[write_index] = nums[read_index]
            write_index += 1

    return write_index

