def is_even_path(grid):
    m, n = len(grid), len(grid[0])
    dp = [[False]*n for _ in range(m)]
    dp[0][0] = (grid[0][0] % 2 == 0)

    for i in range(m):
        for j in range(n):
            if i > 0:
                dp[i][j] |= (dp[i-1][j] and (grid[i][j] % 2 == 0))
            if j > 0:
                dp[i][j] |= (dp[i][j-1] and (grid[i][j] % 2 == 0))

    return dp[m-1][n-1]

def process_operations(operations):
    """
    Processes a list of stack operations and returns the results of 'Top' operations.

    Args:
    operations (list of str): List of stack operations in the format 'Push X', 'Pop', 'Top'.

    Returns:
    list: Results of 'Top' operations in the order they were called.
    """
    stack = []
    result = []

    for operation in operations:
        if operation.startswith("Push"):
            _, value = operation.split()
            stack.append(int(value))
        elif operation == "Pop":
            if stack:
                stack.pop()
        elif operation == "Top":
            if stack:
                result.append(stack[-1])

    return result

