def job_scheduling(startTime, endTime, profit, maxEndTime):
    """
    Returns the maximum profit achievable by selecting non-overlapping jobs within the given end time constraint.
    """
    n = len(startTime)
    jobs = sorted(zip(startTime, endTime, profit), key=lambda x: x[1])
    dp = [0] * (maxEndTime + 1)

    for i in range(n):
        for t in range(maxEndTime, jobs[i][1] - 1, -1):
            if t >= jobs[i][1]:
                dp[t] = max(dp[t], dp[jobs[i][0]] + jobs[i][2])

    return max(dp)

def can_reach_destination(operations):
    results = []

    for op in operations:
        ai, bi, x, y, d = op
        manhattan_distance = abs(x - ai) + abs(y - bi)

        if manhattan_distance <= d and (d - manhattan_distance) % 2 == 0:
            results.append(True)
        else:
            results.append(False)

    return results

def unique_paths_with_obstacles(grid):
    """
    Calculate the number of unique paths in a grid from the top-left to the bottom-right
    corner, where some cells are obstacles (denoted by 1).

    :param grid: List[List[int]] - A 2D grid with 0s and 1s (0 = empty, 1 = blocked)
    :return: int - Number of unique paths
    """
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    m, n = len(grid), len(grid[0])

    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i - 1][j]
                if j > 0:
                    dp[i][j] += dp[i][j - 1]

    return dp[-1][-1]

def search_range(nums, target):
    """
    Returns the starting and ending index of the target in a sorted list.
    If the target is not found, returns [-1, -1].

    :param nums: List[int] - sorted list of integers
    :param target: int - the target value to search for
    :return: List[int] - the starting and ending index of the target
    """
    def binary_search_left(nums, target):
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left

    def binary_search_right(nums, target):
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] <= target:
                left = mid + 1
            else:
                right = mid - 1
        return right

    left_idx = binary_search_left(nums, target)
    right_idx = binary_search_right(nums, target)

    if left_idx <= right_idx and left_idx < len(nums) and nums[left_idx] == target:
        return [left_idx, right_idx]
    else:
        return [-1, -1]

