def find_unique_elements(arr):
    """
    Returns a list of elements that appear only once in the array.

    :param arr: List of integers with some elements appearing twice and some once.
    :return: List of integers that appear only once in the same order as they appear in the input array.
    """
    # Creating a dictionary to store count of each element
    element_count = {}
    for num in arr:
        if num in element_count:
            element_count[num] += 1
        else:
            element_count[num] = 1

    # Creating a list to store elements that appear only once
    unique_elements = [num for num in arr if element_count[num] == 1]

    return unique_elements

