def longest_substring_with_limit(s, limit):
    """
    Find the length of the longest substring with at most 'limit' distinct characters.
    """
    if not s or limit == 0:
        return 0

    start = 0
    max_length = 0
    char_count = {}

    for end in range(len(s)):
        char = s[end]
        char_count[char] = char_count.get(char, 0) + 1

        while len(char_count) > limit:
            start_char = s[start]
            char_count[start_char] -= 1
            if char_count[start_char] == 0:
                del char_count[start_char]
            start += 1

        max_length = max(max_length, end - start + 1)

    return max_length

