def count_good_substrings_of_length_n(s, n):
    """
    Returns the number of good substrings of length n in string s where all characters are distinct.
    """
    if n > len(s):
        return 0

    good_substring_count = 0

    for i in range(len(s) - n + 1):
        substring = s[i:i+n]
        if len(set(substring)) == n:
            good_substring_count += 1

    return good_substring_count

